svg.script:
(function () {
  const DURATION = 12000;
  const PTS = [[73,312.6],[119,312.6],[165,290.1],[211,290.1],[257,312.6],[303,290.1],[349,267.7],[395,290.1],[441,267.7],[487,222.8],[533,200.3],[579,200.3],[625,200.3],[671,177.9],[717,177.9],[763,200.3],[809,177.9],[855,177.9],[901,155.4],[947,177.9],[993,155.4],[1039,155.4],[1085,133],[1131,155.4],[1177,133],[1223,133],[1269,133],[1315,133]];
  const COLS = 28;
  const ROWS = 10;
  const easeOut = t => 1 - Math.pow(1 - t, 3);
  const easeInOut = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const clamp01 = v => Math.max(0, Math.min(1, v));

  const txLogo = document.getElementById('tx-logo');
  const txHead = document.getElementById('tx-head');
  const txSub = document.getElementById('tx-sub');
  const txReadout = document.getElementById('tx-readout');
  const txCardHead = document.getElementById('tx-card-head');
  const txTimeline = document.getElementById('tx-timeline');
  const txStats = document.getElementById('tx-stats');

  const clipRect = document.getElementById('chart-clip-rect');
  const crosshair = document.getElementById('chart-crosshair');
  const halo = document.getElementById('chart-halo');
  const dot = document.getElementById('chart-dot');

  const btcInt = document.getElementById('btc-int');
  const btcDec = document.getElementById('btc-dec');
  const tvlQuote = document.getElementById('tvl-quote');
  const rewardsQuote = document.getElementById('rewards-quote');
  const statBtcTvl = document.getElementById('stat-btc-tvl');
  const statStxTvl = document.getElementById('stat-stx-tvl');
  const statRewards = document.getElementById('stat-rewards');
  const statDefi = document.getElementById('stat-defi');

  const grid = [];
  for (let c = 0; c < COLS; c++) {
    const col = [];
    for (let r = 0; r < ROWS; r++) {
      const el = document.getElementById('c_' + c + '_' + r);
      if (el) col.push({ el, target: el.getAttribute('data-target') || 'led-off' });
    }
    grid.push(col);
  }

  function fadeWindow(t, inStart, inDur, outStart, outDur) {
    if (t < inStart) return 0;
    if (t < inStart + inDur) return easeOut((t - inStart) / inDur);
    if (t <= outStart) return 1;
    if (t < outStart + outDur) return 1 - easeInOut(clamp01((t - outStart) / outDur));
    return 0;
  }

  function updateAt(rawMs) {
    const t = ((rawMs % DURATION) + DURATION) % DURATION;

    // Header visible on frame 0; all texts fade in within <= 460ms
    if (txHead) txHead.setAttribute('opacity', fadeWindow(t, 0, 260, 11500, 480).toFixed(3));
    if (txSub)  txSub.setAttribute('opacity', fadeWindow(t, 90, 280, 11460, 480).toFixed(3));
    if (txReadout) txReadout.setAttribute('opacity', fadeWindow(t, 130, 280, 11440, 480).toFixed(3));
    if (txCardHead) txCardHead.setAttribute('opacity', fadeWindow(t, 80, 260, 11480, 480).toFixed(3));
    if (txTimeline) txTimeline.setAttribute('opacity', fadeWindow(t, 140, 280, 11440, 480).toFixed(3));
    if (txStats) txStats.setAttribute('opacity', fadeWindow(t, 180, 280, 11400, 480).toFixed(3));

    // Chart + LED matrix sweep starts immediately at 250ms -> 6800ms, hold -> 10600ms, return -> 12000ms
    let prog = 0;
    if (t >= 250 && t < 6800) {
      prog = easeInOut((t - 250) / 6550);
    } else if (t >= 6800 && t < 10600) {
      prog = 1;
    } else if (t >= 10600 && t <= 12000) {
      prog = 1 - easeInOut((t - 10600) / 1400);
    }

    const fIdx = prog * (PTS.length - 1);
    const i0 = Math.floor(fIdx);
    const i1 = Math.min(PTS.length - 1, i0 + 1);
    const frac = fIdx - i0;
    const curX = PTS[i0][0] + (PTS[i1][0] - PTS[i0][0]) * frac;
    const curY = PTS[i0][1] + (PTS[i1][1] - PTS[i0][1]) * frac;

    if (clipRect) clipRect.setAttribute('width', prog <= 0.002 ? '0' : Math.max(0, curX - 48 + 2).toFixed(1));
    const dotOp = prog > 0.01 ? clamp01(prog * 10).toFixed(3) : '0';
    if (crosshair) { crosshair.setAttribute('x1', curX.toFixed(1)); crosshair.setAttribute('x2', curX.toFixed(1)); crosshair.setAttribute('opacity', dotOp); }
    if (halo) { halo.setAttribute('cx', curX.toFixed(1)); halo.setAttribute('cy', curY.toFixed(1)); halo.setAttribute('opacity', dotOp); }
    if (dot)  { dot.setAttribute('cx', curX.toFixed(1)); dot.setAttribute('cy', curY.toFixed(1)); dot.setAttribute('opacity', dotOp); }

    const activeCols = prog <= 0.005 ? -1 : Math.floor(fIdx + 0.35);
    for (let c = 0; c < COLS; c++) {
      const col = grid[c];
      const lit = c <= activeCols;
      for (let r = 0; r < col.length; r++) {
        col[r].el.setAttribute('class', lit ? col[r].target : 'led-off');
      }
    }

    const btcVal = (prog * 641.98).toFixed(2).split('.');
    if (btcInt) btcInt.textContent = btcVal[0];
    if (btcDec) btcDec.textContent = btcVal[1];
    if (tvlQuote) tvlQuote.textContent = '$' + (prog * 78.21).toFixed(2) + 'M';
    if (rewardsQuote) rewardsQuote.textContent = (prog * 25.60).toFixed(2) + ' BTC + ' + (prog * 9.18).toFixed(2) + 'M STX earned';
    if (statBtcTvl) statBtcTvl.textContent = '$' + (prog * 41.84).toFixed(2) + 'M';
    if (statStxTvl) statStxTvl.textContent = (prog * 138.9).toFixed(1) + 'M STX';
    if (statRewards) statRewards.textContent = '$' + (prog * 4.09).toFixed(2) + 'M';
    if (statDefi) statDefi.textContent = String(Math.round(prog * 29));
  }

  let manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    updateAt(tMs);
  };

  const start = performance.now();
  function loop(now) {
    if (manual) return;
    updateAt(now - start);
    requestAnimationFrame(loop);
  }
  updateAt(0);
  requestAnimationFrame(loop);
})();
